const response = $json;
const rows = Array.isArray(response?.data) ? response.data : Array.isArray(response) ? response : [];

const findings = rows.map((item) => {
  const attrs = item.attributes || item;
  return {
    provider: attrs.provider || attrs.provider_uid || attrs.account_id || attrs.account || 'unknown',
    service: String(attrs.service || attrs.service_name || '').toLowerCase(),
    severity: String(attrs.severity || '').toLowerCase(),
    status: String(attrs.status || attrs.state || '').toUpperCase(),
    check: attrs.check_id || attrs.check || attrs.title || attrs.uid || 'unknown-check',
    title: attrs.title || attrs.description || attrs.check_id || 'Finding without title',
    region: attrs.region || attrs.region_name || 'global',
    resource: attrs.resource_uid || attrs.resource_id || attrs.resource || ''
  };
}).filter((finding) => {
  const allowedServices = ['iam', 's3', 'cloudtrail'];
  const allowedSeverity = ['critical', 'high'];
  const failedStatuses = ['FAIL', 'FAILED', 'OPEN'];
  return allowedServices.includes(finding.service)
    && allowedSeverity.includes(finding.severity)
    && failedStatuses.includes(finding.status);
});

const bySeverity = findings.reduce((acc, finding) => {
  acc[finding.severity] = (acc[finding.severity] || 0) + 1;
  return acc;
}, {});

const byService = findings.reduce((acc, finding) => {
  acc[finding.service] = (acc[finding.service] || 0) + 1;
  return acc;
}, {});

const byProvider = findings.reduce((acc, finding) => {
  acc[finding.provider] = (acc[finding.provider] || 0) + 1;
  return acc;
}, {});

const topFindings = findings.slice(0, 50);

return [{
  json: {
    generatedAt: new Date().toISOString(),
    prowlerUrl: $env.PROWLER_APP_URL || '',
    totalFindings: findings.length,
    bySeverity,
    byService,
    byProvider,
    topFindings
  }
}];
